sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        //Set assignment group for maker and checker bulk	//original Code

        var loggedInUsr = gs.getUserID();
        var tradeLifecycle = '';
        var tradeStatus = '';
        var marketTask = current.owning_business;
        var taskType = current.bulk_task_type;
        var maker_access = new x_hsb11_mss_c_proc.MSSCustodyBulkUtils().evalMakerAccess();

        var gr = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
        gr.addQuery("bulk_id", current.sys_id);
        gr.query();
        if (gr.next()) {
            tradeStatus = gr.triggered_by.ctac_code;
            tradeLifecycle = gr.trade_id.trade_lifecycle_status;
        }


        var chckr = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
        chckr.get(current.sys_id);

        var newMakerTaskAssignee = chckr.new_maker_task_assignee;
        var currMakerAssignee = chckr.current_maker_assignee;

        gs.info('bulk f new maker' + newMakerTaskAssignee.getDisplayValue() + ' ' + 'curremaker' + currMakerAssignee.getDisplayValue());


        var bps = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage');
        bps.addEncodedQuery('ctac_code=' + tradeStatus + '^market=' + marketTask + '^maker_task_group.nameLIKE' + taskType + '^ORchecker_task_group.nameLIKE' + taskType + '^ORchecker_task_groupLIKEManager');
        bps.query();
        if (bps.next()) {

            if (taskType == 'Maker') {

                current.assignment_group = bps.maker_task_group.sys_id;
                gs.info('bulk f' + chckr.assignment_group.getDisplayValue());
                // if ((chckr.current_maker_assignee == '' || chckr.assigned_to == loggedInUsr) && current.assigned_to != '') {
                //     chckr.setValue('assigned_to', loggedInUsr);
                //     gs.info('bulk f 1');
                // } else if (chckr.new_maker_task_assignee.changes && newMakerTaskAssignee != '' && current.assigned_to != '') { //MSSCUSTODY-3940
                //     chckr.setValue('assigned_to', newMakerTaskAssignee);
                //     gs.info('bulk f 2');
                // } else {
                //     if (current.assigned_to != '') {
                //         chckr.setValue('assigned_to', currMakerAssignee);
                //         gs.info('bulk f 3');
                //     }
                // }
                if (current.new_maker_task_assignee.changes() && current.new_maker_task_assignee != '' && current.assigned_to != '') {
                    current.setValue('assigned_to', current.new_maker_task_assignee);
                    gs.info('bulk f 2');
                } else if ((current.current_maker_assignee == '' || current.assigned_to == loggedInUsr) && current.assigned_to != '') {
                    current.setValue('assigned_to', loggedInUsr);
                    gs.info('bulk f 1');
                } else if (current.assigned_to != '') {
                    current.setValue('assigned_to', current.current_maker_assignee);
                    gs.info('bulk f 3');
                }
                current.update();
                chckr.update();

            } else if (taskType == 'Checker') {
                if (tradeLifecycle == 'TradOnHldDueToSnctns') {
                    var trdType = new GlideRecord('sys_user_group_type');
                    trdType.get(marketTask);
                    var typeID = trdType.sys_id;
                    var grpRole = new GlideRecord('sys_group_has_role');
                    grpRole.addEncodedQuery('role.nameSTARTSWITHx_hsb11_mss_custod.custody_manager^group.typeLIKE' + typeID + '^group.u_group_location=Onshore');
                    grpRole.query();
                    if (grpRole.next()) {
                        chckr.assignment_group = grpRole.getValue('group');
                    }
                } else {
                    chckr.setValue('assignment_group', bps.checker_task_group.sys_id);
                }
                chckr.update();
            }
            // chckr.update();
            //3993
            // if (taskType == 'Maker' && !gs.hasRole('x_hsb11_mss_custod.custody_manager') && (maker_access == true)) {
            //     var grTasks = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
            //     grTasks.addQuery('bulk_id', current.sys_id);
            //     grTasks.addQuery('active', true);
            //     grTasks.addQuery('sub_trade_task_type', 'IN', 'Maker,Automation Failed,Checker-Rejected');
            //     grTasks.query();
            //     while (grTasks.next()) {
            //         grTasks.setValue('assigned_to', chckr.assigned_to);
            //         grTasks.setValue('assignment_group', chckr.assignment_group);
            //         grTasks.setValue('lock', true);
            //         grTasks.update();
            //     }
            // }
        }
    } catch (e) {
        gs.info("Error in bulk form assignment: " + e.message);
    }


})(current, previous);
